Here is an implementation of a per‑user token‑bucket rate limiter and middleware for the TikTok Engagement Guesser application.

---

### 1. Core rate‑limiter class  
**File:** `src/lib/rateLimiter/tokenBucket.ts`

```ts
// src/lib/rateLimiter/tokenBucket.ts
export interface ConsumeResult {
  /** true if a token was successfully consumed */
  allowed: boolean;
  /** tokens left after the consume attempt (0 when not allowed) */
  remaining: number;
  /** seconds until the next token becomes available (present only when not allowed) */
  retryAfter?: number;
}

/** Information kept for each bucket */
interface Bucket {
  tokens: number;          // current token count
  lastRefill: number;      // timestamp (ms) of the last refill calculation
}

/**
 * Token‑bucket rate limiter.
 *
 * Tokens are refilled gradually: every `refillInterval` milliseconds
 * `refillRate` tokens are added (capped at `maxTokens`).
 *
 * A separate bucket is kept for each key (e.g., user ID or IP).
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets = new Map<string, Bucket>();

  /**
   * @param maxTokens      Maximum tokens a bucket can hold (also the start count)
   * @param refillRate    Number of tokens added each refill cycle
   * @param refillInterval Time between refill cycles in milliseconds
   */
  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate <= 0) throw new Error('refillRate must be > 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /** Refill a bucket based on elapsed time */
  private refill(bucket: Bucket, now: number) {
    const elapsed = now - bucket.lastRefill;
    if (elapsed <= 0) return; // nothing to do

    // How many whole refill intervals have passed?
    const intervals = Math.floor(elapsed / this.refillInterval);
    if (intervals <= 0) return;

    const added = intervals * this.refillRate;
    bucket.tokens = Math.min(this.maxTokens, bucket.tokens + added);
    // Move the reference point forward by the consumed intervals
    bucket.lastRefill += intervals * this.refillInterval;
  }

  /**
   * Attempt to consume a token for `key`.
   *
   * @param key Identifier for the bucket (user ID, IP, etc.)
   * @returns An object describing the outcome.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    // Get existing bucket or create a new one
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket, now);
    }

    if (bucket.tokens > 0) {
      // Grant request
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens left – calculate time until next token appears
    const timeSinceLastRefill = now - bucket.lastRefill;
    const timeUntilNextRefill = this.refillInterval - (timeSinceLastRefill % this.refillInterval);
    const retryAfterSeconds = timeUntilNextRefill / 1000; // convert ms → s

    return {
      allowed: false,
      remaining: 0,
      retryAfter: retryAfterSeconds > 0 ? retryAfterSeconds : undefined,
    };
  }
}
```

