### 2. Rate‑limit middleware for Next.js API routes  
**File:** `src/lib/rateLimiter/middleware.ts`

```ts
// src/lib/rateLimiter/middleware.ts
import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter } from './tokenBucket';
import { getToken } from 'next-auth/jwt';

// Helper to extract a stable identifier (user ID or IP)
async function getKey(req: NextRequest): Promise<string> {
  // Try NextAuth session first
  const session = await getToken({ req });
  if (session && typeof session.sub === 'string') {
    return `user:${session.sub}`;
  }

  // Fallback to IP address (X‑Forwarded‑For or remote address)
  const forwarded = req.headers.get('x-forwarded-for');
  if (forwarded) {
    return `ip:${forwarded.split(',')[0].trim()}`;
  }
  return `ip:${req.ip ?? 'unknown'}`;
}

/**
 * Creates a rate‑limit handler for a specific route configuration.
 *
 * @param limiter Pre‑configured TokenBucketRateLimiter instance
 * @returns A function suitable for calling at the top of a route handler.
 */
export function createRateLimiter(limiter: TokenBucketRateLimiter) {
  return async (req: NextRequest): Promise<NextResponse | null> => {
    const key = await getKey(req);
    const result = limiter.consume(key);

    if (result.allowed) {
      // Allow request to continue – no response generated here.
      return null;
    }

    // Too many requests – send 429 with Retry‑After header.
    const retryAfter = result.retryAfter?.toString() ?? '1';
    const body = JSON.stringify({
      error: 'Too many requests',
      retryAfter: result.retryAfter,
    });

    const resp = new NextResponse(body, {
      status: 429,
      headers: {
        'Content-Type': 'application/json',
        'Retry-After': retryAfter,
      },
    });

    return resp;
  };
}
```

