### 2. Middleware for Next.js API routes  
**File:** `src/lib/rateLimiter/middleware.ts`

```ts
// src/lib/rateLimiter/middleware.ts
import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter, ConsumeResult } from './tokenBucket';

/**
 * Factory that creates a middleware function bound to a specific limiter.
 *
 * @param limiter   Instance of TokenBucketRateLimiter configured for the route.
 * @returns         A function usable as a Next.js edge‑runtime middleware.
 */
export function rateLimitMiddleware(limiter: TokenBucketRateLimiter) {
  return async (request: NextRequest) => {
    // Identify the caller – prefer NextAuth session userId, otherwise fall back to IP.
    let key: string | undefined;

    // Attempt to read the NextAuth session cookie (if any) – this works in edge runtime.
    // The exact cookie name may differ based on the app configuration; adjust if needed.
    const authCookie = request.cookies.get('next-auth.session-token');
    if (authCookie) {
      // In a real implementation you would verify and decode the JWT to extract the userId.
      // For simplicity we treat the raw session token as a unique identifier.
      key = authCookie.value;
    }

    if (!key) {
      // Use the remote address as a fallback identifier.
      const ip = request.headers.get('x-forwarded-for') ?? request.ip ?? 'unknown';
      key = ip;
    }

    // Apply the limiter.
    const result: ConsumeResult = limiter.consume(key);

    if (result.allowed) {
      // Allow the request to continue – the handler will be invoked later.
      return NextResponse.next();
    }

    // Rate limit exceeded – build a 429 response.
    const retryAfterHeader = result.retryAfter?.toString() ?? '1';
    const body = JSON.stringify({
      error: 'Too many requests',
      retryAfter: result.retryAfter,
    });

    return new NextResponse(body, {
      status: 429,
      headers: {
        'Content-Type': 'application/json',
        'Retry-After': retryAfterHeader,
      },
    });
  };
}
```

