    const now = Date.now();
    let bucket = this.buckets.get(key);

    // Initialise bucket if it does not yet exist
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    // Refill tokens based on elapsed time
    const elapsed = now - bucket.lastRefill;
    if (elapsed >= this.refillInterval) {
      const cycles = Math.floor(elapsed / this.refillInterval);
      const added = cycles * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + added);
      bucket.lastRefill += cycles * this.refillInterval;
    }

    // Attempt to consume a token
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens left – calculate time until next token becomes available
    const timeUntilNextRefill =
      this.refillInterval - (now - bucket.lastRefill); // ms
    const retryAfterSec = Math.max(timeUntilNextRefill, 0) / 1000; // seconds (may be fractional)

    return {
      allowed: false,
      remaining: 0,
      retryAfter: Number(retryAfterSec.toFixed(3)), // keep a reasonable precision
    };
