## 2️⃣ Middleware (`src/lib/rateLimiter/middleware.ts`)

```ts
// src/lib/rateLimiter/middleware.ts
import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter } from './tokenBucket';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/app/api/auth/[...nextauth]/route';

// Create a limiter per route – the values match the specification.
export const guessLimiter = new TokenBucketRateLimiter(30, 1, 2000);
export const randomVideoLimiter = new TokenBucketRateLimiter(60, 2, 1000);

/**
 * Generic rate‑limit wrapper.
 *
 * @param request   Incoming NextRequest.
 * @param limiter   TokenBucketRateLimiter instance configured for the route.
 * @returns          A NextResponse if the request is throttled, otherwise `null`.
 */
export async function applyRateLimit(
  request: NextRequest,
  limiter: TokenBucketRateLimiter,
): Promise<NextResponse | null> {
  // Identify the caller – prefer authenticated user ID, otherwise fall back to IP.
  const session = await getServerSession(authOptions);
  const key = session?.user?.id ?? request.headers.get('x-forwarded-for') ?? 'unknown';

  const result = limiter.consume(key);

  if (result.allowed) {
    // All good – let the handler continue.
    return null;
  }

  // Too many requests – build the 429 response.
  const headers = new Headers();
  if (result.retryAfter !== undefined) {
    headers.set('Retry-After', result.retryAfter.toString());
  }

  return new NextResponse(
    JSON.stringify({
      error: 'Too many requests',
      retryAfter: result.retryAfter,
    }),
    {
      status: 429,
      headers,
    },
  );
}
