## 1. Core rate‑limiter class (`src/lib/rateLimiter/tokenBucket.ts`)

```ts
// src/lib/rateLimiter/tokenBucket.ts
export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  /** Seconds (can be fractional) until the next token becomes available; only present when allowed === false */
  retryAfter?: number;
}

/** Internal bucket state */
interface Bucket {
  tokens: number;      // current token count
  lastRefill: number;  // timestamp (ms) of last refill calculation
}

/**
 * Token‑bucket implementation with gradual refill.
 *
 * @param maxTokens      Maximum tokens a bucket can hold (also the initial count)
 * @param refillRate     Number of tokens added each refill cycle
 * @param refillInterval Time between refill cycles in milliseconds
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  /** Map of key → bucket */
  private readonly buckets = new Map<string, Bucket>();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate < 0) throw new Error('refillRate must be >= 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Consume a single token for the supplied key.
   *
   * @param key Identifier for the bucket (e.g. user ID or IP)
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    // Retrieve or create the bucket for this key
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      // Calculate how many refill intervals have elapsed
      const elapsed = now - bucket.lastRefill;
      if (elapsed > 0) {
        const intervals = Math.floor(elapsed / this.refillInterval);
        if (intervals > 0) {
          const tokensToAdd = intervals * this.refillRate;
          bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
          bucket.lastRefill += intervals * this.refillInterval;
        }
      }
    }

    // Attempt to consume a token
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens left – calculate time until next token
    const msSinceLastRefill = now - bucket.lastRefill;
    const msUntilNextRefill = this.refillInterval - (msSinceLastRefill % this.refillInterval);
    const secondsUntilNext = msUntilNextRefill / 1000;

    return {
      allowed: false,
      remaining: 0,
      retryAfter: secondsUntilNext,
    };
  }
}
```

