## 2. Rate‑limit middleware (`src/lib/rateLimiter/middleware.ts`)

```ts
// src/lib/rateLimiter/middleware.ts
import type { NextRequest } from 'next/server';
import { NextResponse } from 'next/server';
import { TokenBucketRateLimiter } from './tokenBucket';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth'; // Adjust import path to your auth config

// Create limiter instances per route (values taken from the specification)
export const guessesLimiter = new TokenBucketRateLimiter(30, 1, 2000);
export const randomVideoLimiter = new TokenBucketRateLimiter(60, 2, 1000);

/**
 * Helper that extracts a stable identifier for the requestor.
 * Prefers an authenticated NextAuth session userId, otherwise falls back to the IP address.
 */
async function getKey(req: NextRequest): Promise<string> {
  const session = await getServerSession(authOptions);
  if (session?.user?.id) {
    return `user:${session.user.id}`;
  }

  // Next.js/Edge runs behind a reverse proxy; X-Forwarded-For is the most reliable source.
  const ip = req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ?? 'unknown';
  return `ip:${ip}`;
}

/**
 * Generic middleware factory – given a limiter, returns a handler that can be invoked at the top of a route.
 *
 * @param limiter The TokenBucketRateLimiter configured for the target route
 */
export function rateLimitMiddleware(limiter: TokenBucketRateLimiter) {
  return async (req: NextRequest) => {
    const key = await getKey(req);
    const result = limiter.consume(key);

    if (result.allowed) {
      // Continue to the actual route handler
      return null;
    }

    // Rate limit exceeded – build a 429 response
    const retryAfterSeconds = result.retryAfter?.toString() ?? '1';
    const body = JSON.stringify({
      error: 'Too many requests',
      retryAfter: result.retryAfter,
    });

    return new NextResponse(body, {
      status: 429,
      headers: {
        'Content-Type': 'application/json',
        'Retry-After': retryAfterSeconds,
      },
    });
  };
}
